// Entering a location with the joystick opens its invitation card automatically.
let autoArrivalKey='';
setInterval(()=>{
  const interact=$('#interact');
  if(!interact||panel.open||interact.disabled){ if(interact?.disabled)autoArrivalKey=''; return; }
  const key=interact.textContent.trim();
  if(key!==autoArrivalKey){ autoArrivalKey=key; interact.click(); }
},180);
